arguments.command:
cd /work && python3 -c "
import csv,warnings; warnings.filterwarnings('ignore')
from pymatgen.core import Structure
r={x['candidate_id']:x for x in csv.DictReader(open('nlo_pool.csv'))}
for cid in ['c030','c055','c050','c052','c057','c068','c076','c077','c037','c086','c025','c046']:
    s=Structure.from_str(r[cid]['poscar'],fmt='poscar')
    print(cid, r[cid]['formula'], s.composition.reduced_formula, 'vol/atom=%.1f'%(s.volume/len(s)), [round(x,2) for x in s.lattice.abc])
"

